def build():
    OUT.mkdir(parents=True,exist_ok=True)
    for n in NODES:
        if n.get('kind')=='native_action':
            n['workflow_context']=True
            if n['id']!='western_front':
                n['requirements'].append('Native country-specific political protections permit the action.')
        if n.get('kind')=='proposed_decision':
            n['requirements'].append('No native protection against political intervention is active.')
        for t in n['deals']:
            if t['country']=='United States' and n['id'] not in ('armed','kagnew','berbera'):
                t['modifiers'].pop('Bureaucracy Cost',None)
    ids={n['id'] for n in NODES};assert len(ids)==len(NODES)
    for n in NODES:
        assert all(p in ids for group in n['parents'] for p in group)
        assert not any(c in json.dumps(n,ensure_ascii=False) for c in '\u2013\u2014')
    assets={};notices=[]
    for key,name in ART.items():
        p=(ROOT/'gfx/flags'/(name+'.tga')) if key=='flag_USA' else (ROOT/'gfx/interface/goals'/(name+'.dds'));assert p.exists(),p
        im=Image.open(p).convert('RGBA');im.thumbnail((90,90),Image.Resampling.LANCZOS)
        b=BytesIO();im.save(b,format='PNG');assets[key]='data:image/png;base64,'+base64.b64encode(b.getvalue()).decode()
        notices.append(dict(source=str(p.relative_to(ROOT)).replace('\\','/'),sha256=hashlib.sha256(p.read_bytes()).hexdigest(),credit='Paradox Interactive / Millennium Dawn artists; individual author unknown',licence_or_permission='Unknown; existing upstream terms apply',modifications='Decoded to PNG, maximum 90 pixels, transparency retained; preview only'))
    proposal=dict(project='IMPERIA COLD WAR',date='2026-10-30',status='Design proposal only. No loaded mod changes.',new_focuses=sum(not n['existing'] and n.get('kind','focus')=='focus' for n in NODES),new_decision_proposals=sum(n.get('kind')=='proposed_decision' for n in NODES),existing_context_or_rework=sum(n['existing'] for n in NODES),nodes=NODES,sources=SOURCES,scope='US foreign-policy concept with current neighbouring entries and native global political actions. Not a full installed USA-tree layout.',rules=['Basic channels can coexist. Enhanced funding priorities are exclusive only while active and can be reassigned after consent.','All monetary rates are percentages of current annual GDP; weekly rates are charged weekly without dividing by 52.','Political movement contacts precede statehood. Military assistance needs actual forces, stocks, routes and legal authority.','Governments approve their own cooperative commitments. A hostile government cannot veto opposition operations against it. Moscow cannot withdraw Cuban forces.','Standing bilateral programmes require participation, peace and bilateral sanctions clearance. Original temporary terms keep running during suspension; paid setup and equipment never replay.','Existing MD manipulation, coups and lend-lease are reused. Protest financing is the proposed extra US decision, not an already installed feature.','Effects are balance proposals. Native rendering, execution and live MP are not claimed.'],reference_profile=dict(version='Current checkout MD 2.0.3 / HOI4 1.19.*',md_donor='Main MD 05_russia.txt: SOV_acquire_drones and SOV_fly_byu_drones; native influence/protest systems',pattern='35-day focus, country-scoped aid and mirrored real equipment removal/grant; native manipulation and coups remain their own authoritative actions.',icon_reference='Existing Generic and Russia goal medallions; private web typography approximates native labels.'),art=notices)
    (OUT/'PROPOSAL.json').write_text(json.dumps(proposal,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
    payload=dict(proposal,assets=assets)
    source=(HERE/'preview.template.html').read_text(encoding='utf-8')
    source=re.sub(r'(<script type="application/json" id="af-data">).*?(</script>)',lambda m:m[1]+json.dumps(payload,ensure_ascii=False,separators=(',',':'))+m[2],source,flags=re.S)
    (OUT/'preview.html').write_text(source,encoding='utf-8')
    if VIZ.parent.is_dir():VIZ.write_text(source,encoding='utf-8')
    print(json.dumps(dict(project='IMPERIA COLD WAR',nodes=len(NODES),new=proposal['new_focuses'],preview=str(OUT/'preview.html'),bytes=(OUT/'preview.html').stat().st_size)))

if __name__=='__main__':build()
